/* ------------------------------------------------------------- reveals -- */

function useReveal() {
  const ref = useRef(null)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      el.classList.add('is-in')
      return
    }
    // Fires against the top of the viewport, so a tall region has finished
    // revealing well before the reader has scrolled past it.
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            el.classList.add('is-in')
            io.disconnect()
          }
        })
      },
      { rootMargin: '0px 0px -12% 0px', threshold: 0.01 },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [])
  return ref
}

function Section({ index, id, title, kicker, children, className = '' }) {
  const ref = useReveal()
  return (
    <section id={id} ref={ref} className={`section reveal ${className}`}>
      <header className="section-head">
        <span className="section-num">{index}</span>
        <h2>{title}</h2>
        {kicker ? <p className="section-kicker">{kicker}</p> : null}
      </header>
      {children}
    </section>
  )
}

/* --------------------------------------------------------- power gauge -- */

function ReserveGauge() {
  const [wound, setWound] = useState(false)
  useEffect(() => {
    const t = setTimeout(() => setWound(true), 260)
    return () => clearTimeout(t)
  }, [])
  const R = 86
  const SPAN = 0.75 // three quarters of the dial
  const C = 2 * Math.PI * R
  const arc = C * SPAN
  const start = -215
  return (
    <figure className={`gauge ${wound ? 'is-wound' : ''}`}>
      <svg viewBox="0 0 220 220" role="img" aria-label="Power reserve: 72 hours at full wind">
        <g transform={`rotate(${start} 110 110)`}>
          <circle className="gauge-track" cx="110" cy="110" r={R} strokeDasharray={`${arc} ${C}`} />
          <circle
            className="gauge-fill"
            cx="110"
            cy="110"
            r={R}
            strokeDasharray={`${arc} ${C}`}
            style={{ '--arc': arc }}
          />
        </g>
        {Array.from({ length: 7 }, (_, i) => {
          const a = ((start + (i / 6) * 270) * Math.PI) / 180
          const c = Math.cos(a)
          const s = Math.sin(a)
          const long = i % 2 === 0
          return (
            <line
              key={i}
              className={long ? 'tick tick-long' : 'tick'}
              x1={110 + c * (R - 12)}
              y1={110 + s * (R - 12)}
              x2={110 + c * (R - (long ? 22 : 18))}
              y2={110 + s * (R - (long ? 22 : 18))}
            />
          )
        })}
      </svg>
      <figcaption>
        <span className="gauge-value">72</span>
        <span className="gauge-unit">hours</span>
        <span className="gauge-note">from one wind of 6.5 turns</span>
      </figcaption>
    </figure>
  )
}

/* ----------------------------------------------------------- power path -- */

function PowerPath() {
  const wrapRef = useRef(null)
  const [progress, setProgress] = useState(0)

  const onScroll = useCallback(() => {
    const el = wrapRef.current
    if (!el) return
    const r = el.getBoundingClientRect()
    const vh = window.innerHeight
    // 0 when the list top reaches 78% of the viewport, 1 when its bottom
    // passes 40%. Completes on screen.
    const total = r.height + vh * 0.38
    const done = vh * 0.78 - r.top
    setProgress(Math.max(0, Math.min(1, done / total)))
  }, [])

  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setProgress(1)
      return
    }
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)
    return () => {
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
    }
  }, [onScroll])

  const reached = Math.round(progress * POWER_PATH.length * 1.08)

  return (
    <div className="path" ref={wrapRef}>
      <div className="path-spine" aria-hidden="true">
        <span className="path-spine-fill" style={{ transform: `scaleY(${progress})` }} />
      </div>
      <ol className="path-list">
        {POWER_PATH.map((s, i) => (
          <li key={s.id} data-stage={s.id} className={`path-stage ${i < reached ? 'is-live' : ''}`} tabIndex={0}>
            <span className="path-node">
              <StageMark id={s.id} />
            </span>
            <span className="path-step">{String(i + 1).padStart(2, '0')}</span>
            <div className="path-body">
              <h3>{s.name}</h3>
              <p>{s.detail}</p>
            </div>
            <p className="path-figure">{s.figure}</p>
          </li>
        ))}
      </ol>
    </div>
  )
}

/* --------------------------------------------------------- layer stack -- */

const MM = (t) => parseFloat(t)
const TOTAL_MM = LAYERS.reduce((n, l) => n + MM(l.thickness), 0)

function Stack() {
  const [active, setActive] = useState(null)
  const [exploded, setExploded] = useState(true)

  // Oblique plates. Height of each front edge is the real thickness, to scale.
  const SCALE = 26
  const GAP = 58
  let collapsedY = 0
  const plates = LAYERS.map((l, i) => {
    const h = MM(l.thickness) * SCALE
    const y = collapsedY
    collapsedY += h
    return { ...l, h, collapsedY: y, explodedY: i * GAP }
  })
  const collapsedTop = (4 * GAP + plates[3].h - collapsedY) / 2

  return (
    <div className={`stack ${exploded ? 'is-exploded' : ''}`}>
      <div className="stack-figure">
        <svg viewBox="0 0 460 300" role="img" aria-label="The four plates of Caliber 08, drawn to their real thicknesses">
          <g transform="translate(30 34)">
            {plates.map((p) => {
              const dy = exploded ? p.explodedY : collapsedTop + p.collapsedY
              const dim = active && active !== p.id
              return (
                <g
                  key={p.id}
                  className={`plate ${active === p.id ? 'is-active' : ''} ${dim ? 'is-dim' : ''}`}
                  style={{ transform: `translateY(${dy}px)` }}
                  onMouseEnter={() => setActive(p.id)}
                  onMouseLeave={() => setActive(null)}
                >
                  <polygon className="plate-edge" points={`40,0 280,0 280,${p.h} 40,${p.h}`} />
                  <polygon className="plate-edge2" points={`280,0 380,-46 380,${p.h - 46} 280,${p.h}`} />
                  <polygon className="plate-face" points="40,0 280,0 380,-46 140,-46" />
                  <line className="plate-lead" x1="40" y1={p.h / 2} x2="-24" y2={p.h / 2} />
                </g>
              )
            })}
          </g>
        </svg>
        <button type="button" className="btn btn-quiet stack-toggle" onClick={() => setExploded((v) => !v)}>
          {exploded ? 'Assemble' : 'Separate'} the plates
        </button>
      </div>

      <div className="stack-side">
        <ul className="layer-list">
          {plates.map((l) => (
            <li key={l.id} data-layer={l.id}>
              <button
                type="button"
                className={`layer ${active === l.id ? 'is-active' : ''}`}
                onMouseEnter={() => setActive(l.id)}
                onMouseLeave={() => setActive(null)}
                onFocus={() => setActive(l.id)}
                onBlur={() => setActive(null)}
                aria-pressed={active === l.id}
              >
                <span className="layer-top">
                  <span className="layer-name">{l.name}</span>
                  <span className="layer-mm">{l.thickness}</span>
                </span>
                <span className="layer-bar" aria-hidden="true">
                  <span style={{ width: `${(MM(l.thickness) / TOTAL_MM) * 100}%` }} />
                </span>
                <span className="layer-note">{l.note}</span>
              </button>
            </li>
          ))}
        </ul>
        <p className="stack-total">
          <span>{TOTAL_MM.toFixed(1)}mm</span> of movement, front to back. Every thickness on this page is drawn to
          scale.
        </p>
      </div>
    </div>
  )
}

/* ------------------------------------------------------------ the page -- */

export default function App() {
  const [config, setConfig] = useState('')
  const [name, setName] = useState('')
