      <main id="top">
        {/* ---------------------------------------------------------- hero */}
        <section className="hero" ref={heroRef}>
          <div className="hero-type">
            <p className="eyebrow">Movement · one run of 200</p>
            <h1>
              Caliber<span className="hero-num"> 08</span>
