/* Caliber 08 — Aubry & Vent
   Palette: German silver and paper, one blued-steel accent (the screws), one
   brass note used only for the part of the run that is still available.
   Type: Instrument Serif for statement, IBM Plex Sans for prose, IBM Plex Mono
   for every measured figure. */

:root {
  --paper: #efeae1;
  --paper-2: #e5dfd3;
  --card: #f8f5ef;
  --ink: #191b1e;
  --ink-2: #4d5157;
  --ink-3: #7b7f85;
  --rule: rgba(25, 27, 30, 0.16);
  --rule-soft: rgba(25, 27, 30, 0.09);
  --blue: #23415e;
  --blue-lt: #3d6established;
  --blue-light: #476f9c;
  --brass: #c09147;
  --night: #14171a;
  --night-2: #1c2024;
  --night-ink: #e6e1d7;

  --serif: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --sans: 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --ease-out: cubic-bezier(0.2, 0.8, 0.3, 1);
  --ease-in-out: cubic-bezier(0.6, 0, 0.3, 1);
  --t-fast: 130ms;
  --t-base: 200ms;
  --t-slow: 340ms;

  --page: 1220px;
  --pad: clamp(20px, 5vw, 64px);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1,
h2,
h3 {
  margin: 0;
  font-weight: 400;
  letter-spacing: -0.02em;
}

p {
  margin: 0;
}

ul,
ol,
dl,
dd {
  margin: 0;
  padding: 0;
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
}

::selection {
  background: var(--blue);
  color: var(--paper);
}

/* ---------------------------------------------------- the ambient layer -- */

a,
button,
input,
select,
summary,
.finish,
.layer,
.path-stage {
  transition: color var(--t-fast) var(--ease-out), background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out), box-shadow var(--t-base) var(--ease-out),
    transform var(--t-base) var(--ease-out), opacity var(--t-base) var(--ease-out);
}

:where(a, button, [role='button'], input, select):focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 3px;
}

.reveal {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity var(--t-slow) var(--ease-out), transform var(--t-slow) var(--ease-out);
}

.reveal.is-in {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

/* ------------------------------------------------------------- buttons -- */

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 14px;
  letter-spacing: 0.02em;
  text-decoration: none;
  padding: 13px 22px;
  border: 1px solid var(--ink);
  border-radius: 2px;
  cursor: pointer;
  background: none;
  color: var(--ink);
  line-height: 1;
}

.btn-solid {
  background: var(--ink);
  color: var(--paper);
}

.btn-solid:hover {
  background: var(--blue);
  border-color: var(--blue);
  transform: translateY(-1px);
}

.btn-solid:active {
  transform: translateY(0);
}

.btn-line:hover {
  background: var(--ink);
  color: var(--paper);
  transform: translateY(-1px);
}

.btn-quiet {
  border: 1px solid var(--rule);
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 10px 16px;
  color: var(--ink-2);
  background: var(--card);
}

.btn-quiet:hover {
  color: var(--ink);
  border-color: var(--ink);
  background: var(--paper-2);
}

.btn-sm {
  padding: 9px 15px;
  font-size: 13px;
}

.btn-wide {
  width: 100%;
  justify-content: center;
  padding: 16px 22px;
  font-size: 15px;
}

/* -------------------------------------------------------------- topbar -- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 20px;
  padding: 12px var(--pad);
  background: rgba(239, 234, 225, 0.86);
  backdrop-filter: blur(9px);
  border-bottom: 1px solid transparent;
}

.topbar.is-stuck {
  border-bottom-color: var(--rule);
}

.wordmark {
  font-family: var(--serif);
  font-size: 21px;
  letter-spacing: 0.01em;
  text-decoration: none;
  white-space: nowrap;
}

.wordmark span {
  color: var(--blue);
}

.topbar-mid {
  font-family: var(--mono);
  font-size: 11.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.topbar-run {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--ink-2);
}

.topbar-run strong {
  font-weight: 500;
  color: var(--ink);
}

/* ---------------------------------------------------------------- hero -- */

.hero {
  max-width: var(--page);
  margin: 0 auto;
  padding: clamp(48px, 8vw, 104px) var(--pad) clamp(56px, 8vw, 96px);
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.88fr);
  gap: clamp(24px, 5vw, 72px);
  align-items: center;
}

.eyebrow {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
  margin-bottom: 18px;
}

.hero h1 {
  font-family: var(--serif);
  font-size: clamp(66px, 11.5vw, 158px);
  line-height: 0.84;
  letter-spacing: -0.035em;
}

.hero-num {
  margin-left: 0.1em;
  color: var(--blue);
}

.hero-claim {
  font-family: var(--serif);
  font-size: clamp(22px, 2.3vw, 30px);
  line-height: 1.28;
  margin-top: clamp(22px, 3vw, 34px);
  max-width: 20ch;
}

.hero-lede {
  margin-top: 18px;
  max-width: 46ch;
  color: var(--ink-2);
  font-size: 16.5px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.hero-figures {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  margin-top: clamp(34px, 5vw, 56px);
  border-top: 1px solid var(--rule);
}

.hero-figures > div {
  padding: 14px 14px 0 0;
}

.hero-figures dt {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.hero-figures dd {
  font-family: var(--mono);
  font-size: 19px;
  font-variant-numeric: tabular-nums;
  margin-top: 3px;
}

/* --------------------------------------------------------------- gauge -- */

.gauge {
  margin: 0;
  position: relative;
  display: grid;
  place-items: center;
  justify-self: end;
  width: min(100%, 400px);
}

.gauge svg {
  width: 100%;
  height: auto;
  overflow: visible;
}

.gauge-track,
.gauge-fill {
  fill: none;
  stroke-linecap: butt;
}

.gauge-track {
  stroke: var(--rule);
  stroke-width: 12;
}

.gauge-fill {
  stroke: var(--blue);
  stroke-width: 12;
  stroke-dashoffset: var(--arc);
  transition: stroke-dashoffset 2s var(--ease-out);
}

.gauge.is-wound .gauge-fill {
  stroke-dashoffset: 0;
}

.gauge .tick {
  stroke: var(--ink-3);
  stroke-width: 1;
}

.gauge .tick-long {
  stroke: var(--ink);
  stroke-width: 1.4;
}

.gauge figcaption {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  text-align: center;
  gap: 0;
}

.gauge-value {
  font-family: var(--serif);
  font-size: clamp(58px, 7vw, 88px);
  line-height: 1;
  letter-spacing: -0.03em;
}

.gauge-unit {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-2);
  margin-top: 4px;
}

.gauge-note {
  font-size: 13px;
  color: var(--ink-3);
  margin-top: 12px;
  max-width: 16ch;
  justify-self: center;
  line-height: 1.35;
}

/* ------------------------------------------------------------ sections -- */

.section {
  max-width: var(--page);
  margin: 0 auto;
  padding: clamp(56px, 8vw, 104px) var(--pad);
}

.section-head {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  align-items: baseline;
  column-gap: 8px;
  border-top: 1px solid var(--ink);
  padding-top: 16px;
  margin-bottom: clamp(32px, 5vw, 54px);
}

.section-num {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  color: var(--blue);
}

.section-head h2 {
  font-family: var(--serif);
  font-size: clamp(34px, 4.6vw, 56px);
  line-height: 1.02;
}

.section-kicker {
  grid-column: 2;
  margin-top: 14px;
  max-width: 58ch;
  color: var(--ink-2);
  font-size: 16px;
}

/* ---------------------------------------------------------- power path -- */

.path {
  position: relative;
  padding-left: 0;
}

.path-spine {
  position: absolute;
  left: 25px;
  top: 34px;
  bottom: 34px;
  width: 1px;
  background: var(--rule);
}

.path-spine-fill {
  position: absolute;
  inset: 0;
  background: var(--blue);
  transform-origin: top center;
  transform: scaleY(0);
}

.path-stage {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) minmax(0, 300px);
  column-gap: clamp(18px, 3vw, 40px);
  align-items: start;
  padding: 26px 12px 26px 0;
  border-bottom: 1px solid var(--rule-soft);
  outline-offset: -2px;
}

.path-stage:first-child {
  border-top: 1px solid var(--rule-soft);
}

.path-stage:hover,
.path-stage:focus-visible {
  background: rgba(255, 255, 255, 0.5);
}

.path-node {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 1px solid var(--rule);
  background: var(--paper);
  transition: border-color var(--t-base) var(--ease-out), background-color var(--t-base) var(--ease-out),
    transform var(--t-base) var(--ease-out);
}

.mark {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: var(--ink-3);
  stroke-width: 1.1;
  stroke-linecap: round;
  transition: stroke var(--t-base) var(--ease-out);
}

.path-stage.is-live .path-node {
  border-color: var(--blue);
  background: var(--card);
}

.path-stage.is-live .mark {
  stroke: var(--blue);
}

.path-stage:hover .path-node,
.path-stage:focus-visible .path-node {
  transform: scale(1.06);
  border-color: var(--ink);
}

.path-stage:hover .mark {
  stroke: var(--ink);
}

.path-step {
  display: none;
}

.path-body h3 {
  font-family: var(--serif);
  font-size: clamp(24px, 2.6vw, 32px);
  line-height: 1.1;
}

.path-body p {
  margin-top: 8px;
  color: var(--ink-2);
  font-size: 15.5px;
  max-width: 58ch;
}

.path-figure {
  font-family: var(--mono);
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  line-height: 1.45;
  color: var(--ink-3);
  padding-top: 6px;
  border-top: 2px solid var(--rule);
  transition: color var(--t-base) var(--ease-out), border-color var(--t-base) var(--ease-out);
}

.path-stage.is-live .path-figure {
  color: var(--ink);
  border-top-color: var(--blue);
}

/* --------------------------------------------------------------- stack -- */

.stack {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: start;
}

.stack-figure svg {
  width: 100%;
  height: auto;
  overflow: visible;
}

.plate {
  transition: transform 560ms var(--ease-in-out), opacity var(--t-base) var(--ease-out);
  cursor: pointer;
}

.plate polygon {
  stroke: rgba(25, 27, 30, 0.5);
  stroke-width: 1;
  stroke-linejoin: round;
  transition: fill var(--t-base) var(--ease-out), stroke var(--t-base) var(--ease-out);
}

.plate-face {
  fill: #ddd7c9;
}

.plate-side {
  fill: #c3bcac;
}

.plate-end {
  fill: #b0a897;
}

.plate-lead {
  stroke: var(--rule);
  stroke-width: 1;
}

.plate.is-active .plate-face {
  fill: #f4f0e6;
  stroke: var(--blue);
}

.plate.is-active .plate-side {
  fill: #dcd3c0;
  stroke: var(--blue);
}

.plate.is-active .plate-end {
  fill: #cbc1ac;
  stroke: var(--blue);
}

.plate.is-dim {
  opacity: 0.34;
}

.stack-toggle {
  margin-top: 10px;
}

.layer-list {
  border-top: 1px solid var(--rule);
}

.layer {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  border-bottom: 1px solid var(--rule-soft);
  background: none;
  padding: 15px 14px 16px 0;
  cursor: pointer;
  font: inherit;
}

.layer:hover,
.layer.is-active {
  background: rgba(255, 255, 255, 0.55);
  padding-left: 12px;
  padding-right: 12px;
}

.layer-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
}

.layer-name {
  font-family: var(--serif);
  font-size: 22px;
}

.layer-mm {
  font-family: var(--mono);
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
}

.layer-bar {
  display: block;
  height: 3px;
  background: var(--rule-soft);
  margin: 10px 0 9px;
}

.layer-bar > span {
  display: block;
  height: 100%;
  background: var(--ink-3);
  transition: background-color var(--t-base) var(--ease-out);
}

.layer.is-active .layer-bar > span,
.layer:hover .layer-bar > span {
  background: var(--blue);
}

.layer-note {
  display: block;
  color: var(--ink-2);
  font-size: 15px;
  max-width: 52ch;
}

.stack-total {
  margin-top: 18px;
  color: var(--ink-2);
  font-size: 15px;
  max-width: 46ch;
}

.stack-total span {
  font-family: var(--mono);
  color: var(--ink);
}

/* ----------------------------------------------------------------- spec -- */

.section-spec {
  padding-bottom: clamp(64px, 9vw, 116px);
}

.spec-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: clamp(28px, 5vw, 72px);
  align-items: start;
}

.spec-shout {
  font-family: var(--serif);
  font-size: clamp(24px, 2.5vw, 32px);
  line-height: 1.2;
  max-width: 18ch;
}

.spec-shout span {
  display: block;
  font-size: clamp(96px, 12vw, 168px);
  line-height: 0.82;
  letter-spacing: -0.04em;
  color: var(--blue);
  margin-bottom: 10px;
}

.spec-list {
  border-top: 1px solid var(--ink);
}

.spec-list > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  padding: 11px 0;
  border-bottom: 1px solid var(--rule-soft);
}

.spec-list dt {
  font-size: 15px;
  color: var(--ink-2);
}

.spec-list dd {
  font-family: var(--mono);
  font-size: 15.5px;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

/* ------------------------------------------------------------- atelier -- */

.atelier {
  background: var(--night);
  color: var(--night-ink);
}

.atelier-band {
  position: relative;
  height: clamp(180px, 26vw, 300px);
  overflow: hidden;
}

.atelier-band img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 62%;
  filter: grayscale(0.55) contrast(1.05) brightness(0.62);
}

.atelier-band::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(20, 23, 26, 0.15), var(--night) 96%);
}

.atelier-band-type {
  position: absolute;
  z-index: 1;
  left: var(--pad);
  bottom: 22px;
  right: var(--pad);
  max-width: var(--page);
  margin: 0 auto;
}

.atelier-band-type .section-num {
  color: var(--brass);
  display: block;
  margin-bottom: 6px;
}

.atelier-band-type h2 {
  font-family: var(--serif);
  font-size: clamp(34px, 4.6vw, 56px);
  line-height: 1;
}

.atelier-body {
  max-width: var(--page);
  margin: 0 auto;
  padding: clamp(28px, 4vw, 44px) var(--pad) clamp(56px, 8vw, 92px);
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 0.65fr);
  column-gap: clamp(28px, 4vw, 64px);
  row-gap: clamp(34px, 5vw, 56px);
}

.run {
  align-self: start;
}

.run-head {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: rgba(230, 225, 215, 0.6);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.run-head strong {
  font-weight: 500;
  color: var(--night-ink);
  font-size: 15px;
}

.run-head strong + span + strong,
.run-head > strong:last-of-type {
  color: var(--brass);
}

.run-sep {
  width: 26px;
  height: 1px;
  background: rgba(230, 225, 215, 0.28);
}

.run-grid {
  display: grid;
  grid-template-columns: repeat(25, minmax(0, 1fr));
  gap: 5px 6px;
}

.run-tick {
  height: 18px;
  background: var(--brass);
  transition: background-color var(--t-base) var(--ease-out);
}

.run-tick.is-taken {
  background: rgba(230, 225, 215, 0.16);
}

.run-foot {
  margin-top: 14px;
  font-size: 14px;
  color: rgba(230, 225, 215, 0.6);
}

.lineage {
  margin: 0;
  grid-row: span 2;
}

.lineage img {
  width: 100%;
  height: auto;
  filter: contrast(1.04) saturate(0.86);
}

.lineage figcaption {
  margin-top: 12px;
  font-size: 13.5px;
  line-height: 1.5;
  color: rgba(230, 225, 215, 0.62);
}

.lineage figcaption span {
  display: block;
  margin-top: 6px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: rgba(230, 225, 215, 0.38);
}

.facts {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0;
  border-top: 1px solid rgba(230, 225, 215, 0.2);
}

.facts li {
  padding: 20px 18px 0 0;
  border-right: 1px solid rgba(230, 225, 215, 0.12);
  padding-right: 18px;
}

.facts li:last-child {
  border-right: 0;
}

.fact-lead {
  display: block;
  font-family: var(--serif);
  font-size: clamp(34px, 3.4vw, 46px);
  line-height: 1;
  color: var(--brass);
}

.fact-lead svg {
  display: block;
}

.fact-sub {
  display: block;
  margin-top: 8px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(230, 225, 215, 0.72);
  line-height: 1.4;
}

.facts p {
  margin-top: 10px;
  font-size: 14px;
  line-height: 1.55;
  color: rgba(230, 225, 215, 0.62);
}

/* ------------------------------------------------------------ finishes -- */

.finishes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(14px, 2vw, 24px);
}

.finish {
  display: grid;
  grid-template-rows: auto auto auto auto 1fr auto;
  height: 100%;
  width: 100%;
  text-align: left;
  font: inherit;
  cursor: pointer;
  background: var(--card);
  border: 1px solid var(--rule);
  border-radius: 3px;
  padding: 0 0 0 0;
  overflow: hidden;
}

.finish:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 26px -18px rgba(25, 27, 30, 0.55);
  border-color: var(--ink-3);
}

.finish.is-chosen {
  border-color: var(--blue);
  box-shadow: inset 0 0 0 1px var(--blue);
}

.finish-swatch {
  height: 84px;
  border-bottom: 1px solid var(--rule);
}

.finish-frosted .finish-swatch {
  background: repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.5) 0 1px,
      rgba(0, 0, 0, 0.04) 1px 2px
    ),
    linear-gradient(160deg, #d9d3c5, #b9b2a2 60%, #cfc8b8);
}

.finish-skeleton .finish-swatch {
  background: radial-gradient(circle at 22% 45%, #2a2b2c 0 17%, transparent 17.5%),
    radial-gradient(circle at 52% 68%, #2a2b2c 0 13%, transparent 13.5%),
    radial-gradient(circle at 74% 34%, #2a2b2c 0 15%, transparent 15.5%),
    linear-gradient(150deg, #d7d0c1, #aca493);
}

.finish-black .finish-swatch {
  background: linear-gradient(104deg, #303338 0 34%, #0d0e10 38% 52%, #5b6068 55% 60%, #16181b 64%, #2b2e33);
}

.finish-name {
  font-family: var(--serif);
  font-size: 25px;
  line-height: 1.1;
  padding: 18px 20px 0;
}

.finish-desc {
  padding: 8px 20px 0;
  font-size: 14.5px;
  color: var(--ink-2);
}

.finish-price {
  padding: 16px 20px 0;
  font-family: var(--mono);
  font-size: 26px;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
}

.finish-price em {
  font-style: normal;
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--ink-3);
  margin-right: 4px;
}

.finish-meta {
  padding: 14px 20px 0;
  display: block;
}

.finish-lead {
  display: block;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink-2);
}

.finish-left {
  display: block;
  margin-top: 12px;
  font-size: 13px;
  color: var(--ink-3);
}

.finish-left-bar {
  display: block;
  height: 4px;
  background: var(--rule-soft);
  margin-bottom: 7px;
}

.finish-left-bar > span {
  display: block;
  height: 100%;
  background: var(--brass);
}

.finish-pick {
  margin-top: 18px;
  padding: 13px 20px;
  border-top: 1px solid var(--rule);
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--ink-3);
  background: rgba(255, 255, 255, 0.4);
}

.finish:hover .finish-pick {
  color: var(--ink);
}

.finish.is-chosen .finish-pick {
  background: var(--blue);
  color: var(--paper);
}

/* ------------------------------------------------------------- reserve -- */

.section-reserve {
  padding-bottom: clamp(64px, 9vw, 120px);
}

.reserve {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.82fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: start;
}

.field {
  margin-bottom: 20px;
}

.field label {
  display: block;
  font-family: var(--mono);
  font-size: 11.5px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-2);
  margin-bottom: 7px;
}

.field input,
.field select {
  width: 100%;
  font: inherit;
  font-size: 16px;
  padding: 13px 14px;
  color: var(--ink);
  background: var(--card);
  border: 1px solid var(--rule);
  border-radius: 2px;
  appearance: none;
}

.field select {
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-2) 50%),
    linear-gradient(135deg, var(--ink-2) 50%, transparent 50%);
  background-position: calc(100% - 20px) calc(50% + 1px), calc(100% - 14px) calc(50% + 1px);
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  padding-right: 40px;
}

.field input:hover,
.field select:hover {
  border-color: var(--ink-3);
}

.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(35, 65, 94, 0.14);
}

.slip {
  background: var(--card);
  border: 1px solid var(--rule);
  border-left: 3px solid var(--rule);
  border-radius: 2px;
  padding: 22px 24px 20px;
}

.slip.is-filled {
  border-left-color: var(--blue);
}

.slip-title {
  display: block;
  font-family: var(--mono);
  font-size: 11.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
  padding-bottom: 14px;
  border-bottom: 1px solid var(--rule-soft);
}

.slip dl > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 18px;
  padding: 13px 0;
  border-bottom: 1px dashed var(--rule-soft);
}

.slip dt {
  font-family: var(--mono);
  font-size: 11.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.slip dd {
  text-align: right;
  font-size: 16px;
  max-width: 22ch;
}

.slip-blank {
  color: var(--ink-3);
}

.slip-foot {
  margin-top: 16px;
  font-size: 13px;
  color: var(--ink-3);
}

.slip-done {
  grid-column: 1 / -1;
  border-left-color: var(--blue);
  padding: 30px 32px 26px;
  display: block;
}

.slip-stamp {
  display: inline-block;
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--blue);
  border: 1px solid var(--blue);
  padding: 7px 14px;
  transform: rotate(-2.2deg);
  margin-bottom: 20px;
}

.slip-line {
  display: block;
  font-family: var(--serif);
  font-size: clamp(22px, 2.4vw, 30px);
  line-height: 1.28;
  max-width: 34ch;
}

.slip-line em {
  font-style: normal;
  color: var(--blue);
}

/* -------------------------------------------------------------- footer -- */

.foot {
  border-top: 1px solid var(--ink);
  max-width: var(--page);
  margin: 0 auto;
  padding: clamp(34px, 5vw, 52px) var(--pad) 46px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 22px 32px;
}

.foot-mark {
  font-family: var(--serif);
  font-size: 27px;
}

.foot-mark span {
  color: var(--blue);
}

.foot-addr {
  font-size: 14px;
  color: var(--ink-3);
  margin-top: 2px;
}

.foot-mail {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  font-size: 15px;
  text-decoration: none;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 2px;
}

.foot-mail:hover {
  border-bottom-color: var(--blue);
  color: var(--blue);
}

.foot-links {
  display: grid;
  gap: 8px;
  justify-items: start;
  align-content: start;
  font-size: 14.5px;
}

.foot-links a {
  text-decoration: none;
  color: var(--ink-2);
  border-bottom: 1px solid transparent;
  padding-bottom: 1px;
}

.foot-links a:hover {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.foot-credit {
  grid-column: 1 / -1;
  border-top: 1px solid var(--rule-soft);
  padding-top: 16px;
  font-size: 12.5px;
  color: var(--ink-3);
  max-width: 78ch;
}

.foot-legal {
  grid-column: 1 / -1;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.05em;
  color: var(--ink-3);
}

/* --------------------------------------------------------------- 1080 -- */

@media (max-width: 1080px) {
  .path-stage {
    grid-template-columns: 52px minmax(0, 1fr);
  }
  .path-figure {
    grid-column: 2;
    margin-top: 14px;
    max-width: 34ch;
  }
  .atelier-body {
    grid-template-columns: minmax(0, 1fr);
  }
  .lineage {
    grid-row: auto;
    max-width: 380px;
  }
  .facts {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .facts li {
    padding-bottom: 18px;
    border-bottom: 1px solid rgba(230, 225, 215, 0.12);
  }
}

/* ---------------------------------------------------------------- 860 -- */

@media (max-width: 860px) {
  body {
    font-size: 16.5px;
  }
  .topbar {
    grid-template-columns: auto 1fr auto;
  }
  .topbar-mid {
    display: none;
  }
  .hero,
  .stack,
  .spec-grid,
  .reserve {
    grid-template-columns: minmax(0, 1fr);
  }
  .hero {
    padding-top: 40px;
  }
  .gauge {
    justify-self: center;
    width: min(100%, 300px);
    margin-top: 8px;
  }
  .finishes {
    grid-template-columns: minmax(0, 1fr);
  }
  .spec-shout {
    max-width: none;
  }
  .spec-shout span {
    font-size: clamp(84px, 22vw, 130px);
  }
  .stack-figure {
    order: 2;
  }
  .stack-side {
    order: 1;
  }
}

/* ---------------------------------------------------------------- 620 -- */

@media (max-width: 620px) {
  :root {
    --pad: 20px;
  }
  .topbar {
    grid-template-columns: auto auto;
    justify-content: space-between;
    gap: 12px;
  }
  .topbar-run {
    display: none;
  }
  .hero h1 {
    font-size: clamp(58px, 19vw, 96px);
  }
  .hero-figures {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0 18px;
  }
  .hero-figures > div + div + div {
